/**
 * `ssh <alias>` from any terminal (VS Code Remote, scp, git) for hosts that use key auth.
 * The manager owns one generated file, <data-dir>\ssh_config, rewritten after every host change, so an alias always
 * matches the registry. The user's ~/.ssh/config gets a single `Include` line at the top, added once when a host
 * switches to key auth; the rest of that file is never touched, and the user's own Host names always win (on a clash
 * the alias becomes sshrm-<name>). Password hosts are left out: plain ssh cannot reach the manager's askpass helper.
 */
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { spawnSync } from 'node:child_process';
import { homedir, userInfo } from 'node:os';
import { join } from 'node:path';
import type { DB } from './db.ts';
import { profileOf, type HostRow } from './hosts.ts';
import { cfgPath, knownHostsPath } from './ssh.ts';

export const sshConfigPath = (dataDir: string) => join(dataDir, 'ssh_config');
const userConfigPath = () => join(homedir(), '.ssh', 'config');
const readUserConfig = () => (existsSync(userConfigPath()) ? readFileSync(userConfigPath(), 'utf8') : '');
const norm = (s: string) => s.replaceAll('\\', '/').toLowerCase();
/** Does this text reference our generated file (i.e. contain our Include line)? */
const mentionsOurs = (text: string, dataDir: string) => norm(text).includes(norm(sshConfigPath(dataDir)));

function render(db: DB, dataDir: string) {
  // Host names the user defined themselves (patterns included): ours never shadow them.
  const taken = new Set(readUserConfig().split(/\r?\n/).filter((l) => !mentionsOurs(l, dataDir))
    .flatMap((l) => /^\s*Host\s+(.+)$/i.exec(l)?.[1].split(/\s+/) ?? []).map((h) => h.toLowerCase()));
  const aliases = new Map<string, string>();
  const blocks: string[] = [];
  for (const row of db.prepare('SELECT * FROM hosts WHERE enabled=1 ORDER BY created_at').all() as HostRow[]) {
    const p = profileOf(row);
    if (p.mode !== 'direct' || p.auth === 'password') continue;
    const slug = row.name.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '') || row.id.slice(0, 8);
    let alias = taken.has(slug) ? `sshrm-${slug}` : slug;
    for (let n = 2; taken.has(alias); n++) alias = `sshrm-${slug}-${n}`;
    taken.add(alias);
    aliases.set(row.id, alias);
    blocks.push([`# ${row.name} (host ${row.id})`, `Host ${alias}`, `  HostName ${p.hostname}`, `  Port ${p.port}`, `  User ${p.username}`,
      ...(p.identity_file ? [`  IdentityFile ${cfgPath(p.identity_file)}`] : []), ...(p.identities_only ? ['  IdentitiesOnly yes'] : []),
      ...(p.proxy_jump?.length ? [`  ProxyJump ${p.proxy_jump.join(',')}`] : []),
      `  UserKnownHostsFile ${cfgPath(knownHostsPath(dataDir))}`, '  StrictHostKeyChecking yes'].join('\n'));
  }
  return { aliases, text: `# Generated by SSH Resource Manager from its host registry. Edits are overwritten.\n\n${blocks.join('\n\n')}\n` };
}

/**
 * Windows OpenSSH refuses a private key, and an included config file, that another account can access
 * ("Bad owner or permissions"). Returns the icacls error, or null.
 */
export function restrictToOwner(path: string): string | null {
  if (process.platform !== 'win32') return null;
  const me = process.env.USERDOMAIN ? `${process.env.USERDOMAIN}\\${userInfo().username}` : userInfo().username;
  const r = spawnSync('icacls', [path, '/inheritance:r', '/grant:r', `${me}:F`], { encoding: 'utf8', windowsHide: true, timeout: 10_000 });
  return r.status === 0 ? null : `${r.stdout ?? ''}${r.stderr ?? ''}${r.error?.message ?? ''}`;
}

/** Rewrites the generated file (after every host change). Rewriting keeps the ACL set when it was created. */
export function writeSshConfig(db: DB, dataDir: string) {
  const p = sshConfigPath(dataDir);
  const fresh = !existsSync(p);
  writeFileSync(p, render(db, dataDir).text);
  if (fresh) restrictToOwner(p); // ponytail: on failure ssh reports "Bad permissions" for the alias only; agents use explicit recipes
}

/** Adds the Include line to the top of ~/.ssh/config once (Include must come before any Host block to apply to all). */
export function ensureInclude(dataDir: string) {
  const current = readUserConfig();
  if (mentionsOurs(current, dataDir)) return false;
  mkdirSync(join(homedir(), '.ssh'), { recursive: true });
  writeFileSync(userConfigPath(), `# Added by SSH Resource Manager: aliases for its key-auth hosts. Delete these two lines to opt out.\nInclude ${cfgPath(sshConfigPath(dataDir))}\n\n${current}`);
  return true;
}

/** The host's alias when ~/.ssh/config includes the generated file, else null. Read-only. */
export function sshAlias(db: DB, dataDir: string, hostId: string) {
  return mentionsOurs(readUserConfig(), dataDir) ? render(db, dataDir).aliases.get(hostId) ?? null : null;
}
